func handleLogin(c *gin.Context) {
	var req struct {
		Username string `json:"username" binding:"required"`
		Password string `json:"password" binding:"required"`
	}

	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request"})
		return
	}

	// Create CGO session context
	session := C.create_session()
	defer C.free_session(session)

	// Vulnerable: username from user input copied without length check
	// into 64-byte buffer, overflowing into role[16] and authenticated fields
	cUsername := C.CString(req.Username)
	defer C.free(unsafe.Pointer(cUsername))
	C.set_username(session, cUsername)

	// Check if session now has admin (can be achieved via overflow)
	if C.check_admin(session) == 1 {
		c.JSON(http.StatusOK, gin.H{
			"message": "Welcome, administrator",
			"token":   "admin-jwt-token-xyz789",
		})
		return
	}

	// Normal auth check (simplified)
	if req.Username == "user" && req.Password == "password123" {
		c.JSON(http.StatusOK, gin.H{
			"message": "Login successful",
			"token":   "user-jwt-token-abc123",
		})
		return
	}

	c.JSON(http.StatusUnauthorized, gin.H{"error": "invalid credentials"})
}

func handleAdminPanel(c *gin.Context) {
